20	        await asAdmin(page, '/footy/admin/responses');
21	
22	        await expect(page.getByRole('heading', { name: /Responses/i })).toBeVisible();
23	
24	        // Read a group's player count from its h2 heading ("Yes: 15").
25	        // CSS + text filter works regardless of whether the card has an explicit ARIA role.
26	        const groupCount = async (title: string) => {
27	            const heading = page.locator('h2').filter({ hasText: new RegExp(`^${title}:\\s*`) });
28	            if (await heading.count() === 0) return 0;
29	            const text = await heading.first().innerText();
30	            const match = /:\s*(\d+)$/.exec(text.trim());
31	            return match ? Number(match[1]) : 0;
32	        };
33	
34	        const initialYes = await groupCount('Yes');
35	        const initialNo = await groupCount('No');
36	        const initialDunno = await groupCount('Dunno');
37	        const initialNone = await groupCount('None');
38	
39	        const startsFromNone = initialNone > 0;
40	        const yesAfterFirstUpdate = startsFromNone ? initialYes + 1 : initialYes;
41	        const noneAfterFirstUpdate = startsFromNone ? initialNone - 1 : initialNone;
