39	interface ResponsesFormProps {
40	    gameId: number;
41	    gameDate: string;
42	    responses: OutcomePlayerType[];
43	    submitResponse: SubmitResponseProxy;
44	}
45	
46	type ResponseOption = PlayerResponse | 'None';
47	const ResponseOption = {
48	    ...PlayerResponse,
49	    None: 'None' as const,
50	};
51	
52	type ResponseValues = Pick<OutcomePlayerType, 'response' | 'goalie' | 'comment'>;
53	interface ResponsesFormValues {
54	    byPlayerId: Record<number, ResponseValues>;
55	}
56	
57	const toResponseValues = (row: OutcomePlayerType): ResponseValues => ({
58	    response: row.response ?? null,
59	    goalie: !!row.goalie,
60	    // v8 ignore next -- comment is always a string in practice (Prisma default '')
61	    comment: row.comment ?? '',
62	});
63	
64	const responseGroupBarColor: Record<ResponseOption, MantineColor> = {
65	    [ResponseOption.Yes]: 'green.6',
66	    [ResponseOption.No]: 'red.6',
67	    [ResponseOption.Dunno]: 'yellow.6',
68	    [ResponseOption.Excused]: 'gray.6',
69	    [ResponseOption.Flaked]: 'gray.6',
70	    [ResponseOption.Injured]: 'gray.6',
71	    [ResponseOption.None]: 'gray.6',
72	};
73	
74	export const ResponsesForm = ({
75	    gameId,
76	    gameDate,
77	    responses,
78	    submitResponse,
79	}: ResponsesFormProps) => {
80	    const form = useForm<ResponsesFormValues>({
81	        initialValues: {
82	            byPlayerId: Object.fromEntries(responses.map((row) => [row.playerId, toResponseValues(row)])),
83	        },
84	    });
85	    const [savingId, setSavingId] = useState<number | null>(null);
86	    const [filter, setFilter] = useState('');
87	    const [expandedGroups, setExpandedGroups] = useState<Set<ResponseOption>>(new Set());
88	    const isFiltering = filter.trim().length > 0;
89	
90	    const toggleGroup = (title: ResponseOption) => {
91	        setExpandedGroups((prev) => {
92	            const next = new Set(prev);
93	            if (next.has(title)) {
94	                next.delete(title);
95	            } else {
96	                next.add(title);
97	            }
98	            return next;
99	        });
100	    };
101	
102	    // Re-sync form values when the responses prop changes (e.g. after
103	    // revalidate / SSE refresh). Preserve any in-progress edits by only
104	    // overwriting rows whose form values still match the previous baseline.
105	    const prevResponsesRef = useRef(responses);
106	    useEffect(() => {
107	        const prevBaselineById = new Map(
108	            prevResponsesRef.current.map((row) => [row.playerId, toResponseValues(row)]),
109	        );
110	        for (const row of responses) {
111	            const newBaseline = toResponseValues(row);
112	            const oldBaseline = prevBaselineById.get(row.playerId) ?? newBaseline;
113	            const current = form.values.byPlayerId[row.playerId];
114	            const userEdited =
115	                !!current && (
116	                    current.response !== oldBaseline.response ||
117	                    current.goalie !== oldBaseline.goalie ||
118	                    current.comment !== oldBaseline.comment
119	                );
120	            if (!userEdited) {
121	                form.setFieldValue(`byPlayerId.${row.playerId}`, newBaseline);
122	            }
123	        }
124	        prevResponsesRef.current = responses;
125	        // eslint-disable-next-line react-hooks/exhaustive-deps -- form identity is stable; we only want to react to responses changes
126	    }, [responses]);
127	
128	    const isRowDirty = (row: OutcomePlayerType) => {
129	        const baseline = toResponseValues(row);
130	        // v8 ignore next -- form is always initialised from the same rows array
131	        const current = form.values.byPlayerId[row.playerId] ?? baseline;
132	
133	        return (
134	            baseline.response !== current.response ||
135	            baseline.goalie !== current.goalie ||
136	            baseline.comment !== current.comment
137	        );
138	    };
139	
140	    const grouped = useMemo(() => {
141	        const filteredRows = responses.filter((row) => {
142	            const searchTerm = filter.toLowerCase();
143	            // v8 ignore next -- optional chaining on name is a type-safety guard
144	            return (row.player.name?.toLowerCase().includes(searchTerm));
145	        });
146	
147	        return {
148	            yes: filteredRows.filter((r) => r.response === ResponseOption.Yes),
149	            no: filteredRows.filter((r) => r.response === ResponseOption.No),
150	            dunno: filteredRows.filter((r) => r.response === ResponseOption.Dunno),
151	            excused: filteredRows.filter((r) => r.response === ResponseOption.Excused),
152	            flaked: filteredRows.filter((r) => r.response === ResponseOption.Flaked),
153	            injured: filteredRows.filter((r) => r.response === ResponseOption.Injured),
154	            none: filteredRows.filter((r) => r.response == null),
155	        };
156	    }, [responses, filter]);
157	
158	    const handleSubmit = async (row: OutcomePlayerType) => {
159	        // v8 ignore next -- form is always initialised from the same rows array
160	        const responseValues = form.values.byPlayerId[row.playerId] ?? toResponseValues(row);
161	        if (!responseValues.response) return;
162	
163	        const notificationId = `response-${row.playerId}`;
164	        notifications.show({
165	            id: notificationId,
166	            loading: true,
167	            title: 'Updating response',
168	            message: 'Updating response...',
169	            autoClose: false,
170	            withCloseButton: false,
171	        });
172	
173	        setSavingId(row.playerId);
174	        try {
175	            await submitResponse({
176	                gameDayId: gameId,
177	                playerId: row.playerId,
178	                response: responseValues.response,
179	                goalie: !!responseValues.goalie,
180	                // v8 ignore next -- form normalises null to '' at init, so comment is always a string
181	                comment: responseValues.comment ?? null,
182	            });
183	            notifications.update({
184	                id: notificationId,
185	                color: 'teal',
186	                title: 'Response updated',
187	                message: 'Response updated successfully',
188	                icon: <IconCheck size={config.notificationIconSize} />,
189	                loading: false,
190	                autoClose: config.notificationAutoClose,
191	            });
192	        } catch (err) {
193	            const errorMessage = err instanceof Error ? err.message : 'Failed to update response';
194	            notifications.update({
195	                id: notificationId,
196	                color: 'red',
197	                title: 'Error',
198	                message: errorMessage,
199	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
200	                loading: false,
201	                autoClose: false,
202	                withCloseButton: true,
203	            });
204	        } finally {
205	            setSavingId(null);
206	        }
207	    };
208	
209	    const renderGroup = (title: ResponseOption, items: OutcomePlayerType[]) => {
210	        if (items.length === 0) return null;
211	
212	        const opened = expandedGroups.has(title) || isFiltering;
213	
214	        return (
215	            <Card key={title} withBorder shadow="xs" p="md" role="region" aria-label={title}>
216	                <CardSection h={6} bg={responseGroupBarColor[title]} />
217	                <UnstyledButton onClick={() => toggleGroup(title)} aria-expanded={opened} w="100%" mt="md">
218	                    <Group justify="space-between">
219	                        <Title
220	                            order={2}
221	                        >
222	                            {title}:{' '}
223	                            <Tooltip
224	                                multiline
225	                                label={items.map((item) => item.player.name).join(', ')}
226	                            >
227	                                <Text span inherit>{items.length}</Text>
228	                            </Tooltip>
229	                        </Title>
230	                        <IconChevronDown
231	                            size={20}
232	                            style={{
233	                                transform: opened ? 'rotate(180deg)' : 'rotate(0deg)',
234	                                transition: 'transform 150ms ease',
235	                            }}
236	                        />
237	                    </Group>
238	                </UnstyledButton>
239	                <Collapse expanded={opened}>
240	                    <Stack gap="sm" mt="lg">
241	                        {items.map((row) => {
242	                            // v8 ignore next -- form is always initialised from the same rows array
243	                            const responseValues = form.values.byPlayerId[row.playerId] ?? toResponseValues(row);
244	                            // v8 ignore next -- null names are excluded by the search filter before rows are rendered
245	                            const ariaLabel = row.player.name ?? `Player ${row.playerId}`;
246	                            return (
247	                                <Flex
248	                                    key={row.playerId}
249	                                    role="group"
250	                                    aria-label={ariaLabel}
251	                                    data-player-id={row.playerId}
252	                                    wrap="wrap"
253	                                    align="center"
254	                                    gap="sm"
255	                                    bd="1px solid var(--mantine-color-gray-3)"
256	                                    p="sm"
257	                                    bdrs="sm"
258	                                >
259	                                    <Text
260	                                        fw={600}
261	                                        miw="15rem"
262	                                    >
263	                                        {row.player.name}
264	                                    </Text>
265	                                    <Select
266	                                        aria-label="Response"
267	                                        data={Object.values(PlayerResponse).map((option) => ({
268	                                            value: option,
269	                                            label: option,
270	                                        }))}
271	                                        value={responseValues.response ?? ResponseOption.None}
272	                                        onChange={(value) => {
273	                                            const nextValue = value;
274	                                            form.setFieldValue(
275	                                                `byPlayerId.${row.playerId}.response`,
276	                                                // v8 ignore next -- 'None' never appears in the Select data array
277	                                                nextValue === ResponseOption.None ? null : nextValue,
278	                                            );
279	                                        }}
280	                                        size="sm"
281	                                        w="7rem"
282	                                    />
283	                                    <Checkbox
284	                                        label="Goalie"
285	                                        size="sm"
286	                                        {...form.getInputProps(
287	                                            `byPlayerId.${row.playerId}.goalie`,
288	                                            { type: 'checkbox' },
289	                                        )}
290	                                    />
291	                                    <Textarea
292	                                        autosize
293	                                        minRows={1}
294	                                        aria-label="Comment"
295	                                        placeholder="Comment"
296	                                        maxLength={127}
297	                                        {...form.getInputProps(`byPlayerId.${row.playerId}.comment`)}
298	                                        size="sm"
299	                                        flex={1}
300	                                        miw={{ base: "9rem", sm: "16rem" }}
301	                                    />
302	                                    <Button
303	                                        variant="filled"
304	                                        size="sm"
305	                                        disabled={!isRowDirty(row)}
306	                                        loading={savingId === row.playerId}
307	                                        onClick={() => handleSubmit(row)}
308	                                        w="6rem"
309	                                    >
310	                                        Update
311	                                    </Button>
312	                                </Flex>
313	                            );
314	                        })}
315	                    </Stack>
316	                </Collapse>
317	            </Card>
318	        );
319	    };
320	
321	    return (
322	        <Container size="lg" p={0}>
323	            <Paper w="100%">
324	                <Stack gap="md">
325	                    <Stack align="flex-start" gap="xs">
326	                        <Title order={2}>Responses</Title>
327	                        <Text c="dimmed">Game {gameId}: {gameDate}</Text>
328	                        <TextInput
329	                            label="Search players"
330	                            placeholder="Search players"
331	                            value={filter}
332	                            onChange={(event) => setFilter(event.currentTarget.value)}
333	                            w="100%"
334	                        />
335	                    </Stack>
336	                    {Object.values(ResponseOption).map((option) => (
